={{
(() => {
  const raw = $('檢視病例').first().json.profile_json ?? {};
  const p = typeof raw === 'string' ? JSON.parse(raw) : raw;
  const render = (value) => {
    if (value === null || value === undefined) return '尚未提供';
    const text = Array.isArray(value) ? value.join('、').trim() : String(value).trim();
    if (!text) return '尚未提供';
    const normalized = text.toLowerCase();
    if (normalized === 'unknown') return '不確定';
    if (normalized === 'none') return '無';
    if (normalized === 'declined') return '使用者選擇不回答';
    return text;
  };
  return `目前資料庫中儲存的基本病歷如下：

年齡或年齡區間：${render(p.age_range)}
出生時生理性別：${render(p.sex_at_birth)}
過敏：${render(p.allergies)}
慢性疾病：${render(p.chronic_conditions)}
長期使用藥物：${render(p.regular_medications)}

以上病歷資料是否需要更改？請回答「不需要」，或告訴我要修改哪一項。`;
})()
}}

