={{
(() => {
  const current = $('檢視病例').first().json.profile_json ?? {};
  const incoming = $json.output?.patient_profile ?? $json.patient_profile ?? {};
  const merged = {
    ...(typeof current === 'object' && current !== null ? current : {})
  };
  for (const key of [
    'preferred_name',
    'age_range',
    'sex_at_birth',
    'allergies',
    'chronic_conditions',
    'regular_medications'
  ]) {
    const value = incoming[key];
    const text = Array.isArray(value) ? value.join('、').trim() : (value == null ? '' : String(value).trim());
    if (text) merged[key] = value;
  }
  return [
    'age_range',
    'sex_at_birth',
    'allergies',
    'chronic_conditions',
    'regular_medications'
  ].every((key) => {
    const value = merged[key];
    return value !== null && value !== undefined && (Array.isArray(value) ? value.length > 0 : String(value).trim() !== '');
  });
})()
}}

