parameters.jsCode:
const input = $input.first();
const payload = input.json.body && typeof input.json.body === 'object' ? input.json.body : {};
const events = Array.isArray(payload.events) ? payload.events : [];
const event = events.find((candidate) =>
  candidate &&
  candidate.type === 'message' &&
  candidate.message &&
  candidate.message.type === 'text' &&
  typeof candidate.message.text === 'string' &&
  candidate.replyToken
);
if (!event) return [];
const source = event.source || {};
const sourceId = source.userId || source.groupId || source.roomId;
if (!sourceId) return [];
const channelType = String(source.type || 'user');
return [{
  json: {
    ...input.json,
    platform: 'line',
    authorId: `line:${sourceId}`,
    channelId: `line:${channelType}:${sourceId}`,
    content: event.message.text,
    replyToken: event.replyToken,
    webhookEventId: String(event.webhookEventId || event.message.id || ''),
    lineValidEvent: true,
  },
  binary: input.binary,
  pairedItem: { item: 0 },
}];
